package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.maze.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.*;
import net.minecraft.world.level.Level;
import net.minecraftforge.gametest.*;
import tc4revival.content.*;
@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class MazeServerTests {
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void mazeProvidersRejectOverridesAndPersistIndependentDimension(GameTestHelper test){var server=test.getLevel().getServer();var level=server.getLevel(MazeSessions.DIMENSION);test.assertTrue(level!=null,"Additional dimension loads from actual datapack");var original=EldritchMazeSavedData.get(server);test.assertTrue(EldritchMazeSavedData.get(server.overworld())==original&&EldritchMazeSavedData.get(server.getLevel(Level.NETHER))==original,"Unregistered dimensions retain original core storage");test.assertTrue(EldritchMazeSavedData.get(level)!=original&&EldritchMazeSavedData.isMazeDimension(MazeSessions.DIMENSION),"Registered dimension has its own actual SavedData");boolean duplicate=false,outer=false;try{EldritchMazeSavedData.registerDimension(MazeSessions.DIMENSION,l->original);}catch(IllegalArgumentException expected){duplicate=true;}try{EldritchMazeSavedData.registerDimension(TCEldritch.OUTER_LANDS,l->original);}catch(IllegalArgumentException expected){outer=true;}test.assertTrue(duplicate&&outer,"Duplicate registration and original outer-lands override rejected");var data=MazeSessionsData.get(level);int cx=data.nextCenter;data.nextCenter+=30;var owner=java.util.UUID.randomUUID();var layout=EldritchMazeLayout.generate(7,7,12345);var s=MazeSessions.create(data,owner,Level.OVERWORLD,new net.minecraft.world.phys.Vec3(13,75,19),BlockPos.ZERO,cx,29,layout);data.mazes.assignBoss(cx,29,1);s.bossSeen=true;s.bosses.put(java.util.UUID.randomUUID(),new BlockPos(cx*16,55,464));var restored=MazeSessionsData.load(data.save(new CompoundTag()));test.assertTrue(restored.mazes.readable()&&restored.mazes.plan(cx,29).isPresent()&&restored.sessions.get(owner).bosses.equals(s.bosses)&&restored.sessions.get(owner).originPos.equals(s.originPos),"Maze, origin and live boss identity survive save/load");test.assertTrue(original.plan(cx,29).isEmpty(),"Additional maze never enters original dimension's plans");s.closed=true;s.buildIndex=layout.width()*layout.height();MazeSessions.cleanup(level,data,s);test.assertTrue(!data.sessions.containsKey(owner)&&data.mazes.plan(cx,29).isEmpty(),"Closing instance removes only its plan");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty",timeoutTicks=300)
    public static void actualCoreLockUsesAdditionalMazeBossAndCreatesReturnExit(GameTestHelper test){var level=test.getLevel().getServer().getLevel(MazeSessions.DIMENSION);var data=MazeSessionsData.get(level);int cx=data.nextCenter;data.nextCenter+=30;int[] cells=new int[49];cells[4+4*7]=new EldritchMazeLayout.Cell(1,1).packed();cells[0]=new EldritchMazeLayout.Cell(4,2).packed();cells[1]=new EldritchMazeLayout.Cell(0,3).packed();cells[7]=new EldritchMazeLayout.Cell(0,4).packed();cells[8]=new EldritchMazeLayout.Cell(0,5).packed();var layout=EldritchMazeLayout.restore(7,7,7,cells);var s=MazeSessions.create(data,java.util.UUID.randomUUID(),Level.OVERWORLD,net.minecraft.world.phys.Vec3.ZERO,BlockPos.ZERO,cx,29,layout);var plan=data.mazes.plan(cx,29).orElseThrow();data.mazes.assignBoss(cx,29,0);for(int z=0;z<2;z++)for(int x=0;x<2;x++){var cell=layout.cell(x,z);EldritchMazePlacer.generate(level,plan.originX()+x,plan.originZ()+z,cell);data.mazes.markGenerated(plan.originX()+x,plan.originZ()+z);}BlockPos lockPos=null;for(var p:BlockPos.betweenClosed(plan.originX()*16,50,plan.originZ()*16,plan.originX()*16+32,65,plan.originZ()*16+32))if(level.getBlockEntity(p) instanceof EldritchLockBlockEntity){lockPos=p.immutable();break;}test.assertTrue(lockPos!=null,"Actual original boss room builds a lock");var lock=(EldritchLockBlockEntity)level.getBlockEntity(lockPos);test.assertTrue(lock.activate(),"Original lock activates inside addon dimension");for(int i=0;i<101;i++)lock.tick();test.assertTrue(!level.getBlockState(lockPos).is(TCEldritch.LOCK.get())&&s.bossSeen&&!s.bosses.isEmpty(),"Lock opens real arena and tracked boss using dimension provider");for(var id:new java.util.ArrayList<>(s.bosses.keySet())){var entity=level.getEntity(id);test.assertTrue(entity!=null&&entity.getType()==TCEntities.ELDRITCH_GOLEM.get(),"Assigned original golem encounter spawned");entity.discard();}test.runAfterDelay(2,()->{test.assertTrue(s.bosses.isEmpty(),"Destroyed boss removal event clears persisted watcher");MazeSessions.openExit(level,s);test.assertTrue(s.exitOpened&&level.getBlockState(new BlockPos(cx*16+8,53,29*16+8)).is(Gadomancy.ADDITIONAL_PORTAL.get()),"Boss completion creates actual return portal at entrance");s.closed=true;s.buildIndex=layout.width()*layout.height();MazeSessions.cleanup(level,data,s);test.succeed();});}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void generatedEntranceHasNoPrematureExitAndEntryIsTransactional(GameTestHelper test){var origin=test.getLevel();var level=origin.getServer().getLevel(MazeSessions.DIMENSION);var data=MazeSessionsData.get(level);int cx=data.nextCenter;data.nextCenter+=30;int[] cells=new int[49];cells[4+4*7]=new EldritchMazeLayout.Cell(1,1).packed();var layout=EldritchMazeLayout.restore(7,7,43,cells);var p=NodeServerTests.player(test);var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}};new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,connection,p);var at=test.absolutePos(new BlockPos(3,3,3));origin.setBlockAndUpdate(at,Gadomancy.ADDITIONAL_PORTAL.get().defaultBlockState());p.setPos(at.getCenter());origin.addNewPlayer(p);var returnPos=p.position();var s=MazeSessions.create(data,p.getUUID(),origin.dimension(),returnPos,at,cx,29,layout);try{test.assertTrue(!MazeSessions.enter(level,data,s,p)&&origin.getBlockState(at).is(Gadomancy.ADDITIONAL_PORTAL.get()),"Incomplete maze never consumes entry portal");MazeSessions.buildOne(level,data,s);for(int i=52;i<=59;i++)test.assertTrue(!level.getBlockState(new BlockPos(cx*16+8,i,29*16+8)).is(TCEldritch.PORTAL.get()),"Entry room suppresses original immediate exit");s.buildIndex=49;test.assertTrue(MazeSessions.enter(level,data,s,p)&&p.level()==level&&!origin.getBlockState(at).is(Gadomancy.ADDITIONAL_PORTAL.get()),"Complete room really transfers player and consumes source portal");test.assertTrue(MazeSessions.close(p,true)&&p.level()==origin&&p.position().distanceToSqr(returnPos)<.0001,"Exit returns to exact original dimension and position");}finally{p.discard();s.closed=true;s.buildIndex=49;MazeSessions.cleanup(level,data,s);}test.succeed();}
}
